const verifiedSource=Symbol('v89 exact printed source');
export function normalizeCard(card,original){const source=SOURCES[original.name],valid=source&&Object.entries(source).every(([key,value])=>original[key]===value);return {...card,[verifiedSource]:valid?original.name:null};}
export function compileWholeCard(card,h){const name=card[verifiedSource];if(!name)return null;const op={kind:'creature-rule-v89',mode:name,contract:'generic-trigger-effect'};return {semanticClass:'creature-template',implementation:[op],implementedKeywords:[],oracleContracts:[op.contract],rulesCore:h.stripReminderText(card.oracle_text)};}
